import{_ as d,o as e,c as r,a2 as o}from"./chunks/framework.CWWEQfK7.js";const p=JSON.parse('{"title":"命令速查","description":"查找 Ershu 部署、后端组件、前端和文档站点常用的安装、运行与检查命令。","frontmatter":{"page_id":"reference-commands","title":"命令速查","description":"查找 Ershu 部署、后端组件、前端和文档站点常用的安装、运行与检查命令。"},"headers":[],"relativePath":"reference/commands.md","filePath":"reference/commands.md","lastUpdated":1786627803000}'),c={name:"reference/commands.md"};function s(a,t,u,n,h,l){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="命令速查" tabindex="-1">命令速查 <a class="header-anchor" href="#命令速查" aria-label="Permalink to &quot;命令速查&quot;">​</a></h1><p>服务器命令使用快速部署中的固定目录。开发命令从表格写明的仓库根目录运行。后端统一使用 UV，不要把一个组件的锁文件复制到另一个组件。</p><h2 id="已安装的-linux-服务器" tabindex="-1">已安装的 Linux 服务器 <a class="header-anchor" href="#已安装的-linux-服务器" aria-label="Permalink to &quot;已安装的 Linux 服务器&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目的</th><th>命令</th></tr></thead><tbody><tr><td>安装当前发布包</td><td><code>sudo bash deploy/systemd/install.sh --uv-bin &quot;$(command -v uv)&quot;</code></td></tr><tr><td>启动完整后端</td><td><code>sudo systemctl enable --now ershu.target</code></td></tr><tr><td>查看后端状态</td><td><code>sudo systemctl status ershu-api ershu-worker ershu-mcp</code></td></tr><tr><td>重启完整后端</td><td><code>sudo systemctl restart ershu.target</code></td></tr><tr><td>停止完整后端</td><td><code>sudo systemctl stop ershu.target</code></td></tr><tr><td>查看后端日志</td><td><code>journalctl -u ershu-api -u ershu-worker -u ershu-mcp -f</code></td></tr><tr><td>查看基础设施</td><td><code>sudo systemctl status ershu-infrastructure</code></td></tr><tr><td>启用计划轮询</td><td><code>sudo systemctl enable --now ershu-poller.service</code></td></tr><tr><td>查看数据库升级头</td><td><code>/opt/ershu/current/.venv/bin/ershu-db heads</code></td></tr><tr><td>查看目标数据库当前版本</td><td><code>sudo -u ershu sh -c &#39;cd /etc/ershu &amp;&amp; /opt/ershu/current/.venv/bin/ershu-db current&#39;</code></td></tr></tbody></table><p>完整顺序见<a href="/guide/quick-start">Linux 服务器快速部署</a>。</p><h2 id="后端组件检查" tabindex="-1">后端组件检查 <a class="header-anchor" href="#后端组件检查" aria-label="Permalink to &quot;后端组件检查&quot;">​</a></h2><p>先在对应仓库运行安装命令，再运行检查。</p><table tabindex="0"><thead><tr><th>仓库</th><th>安装</th><th>测试</th><th>代码与格式</th><th>构建</th></tr></thead><tbody><tr><td><code>ershu-core</code></td><td><code>uv sync --locked</code></td><td><code>uv run pytest -m &quot;not integration&quot;</code></td><td><code>uv run ruff check src tests</code><br><code>uv run ruff format --check src tests</code></td><td><code>uv build --no-sources</code></td></tr><tr><td><code>ershu-api</code></td><td><code>uv sync --locked --extra dev</code></td><td><code>uv run --extra dev pytest -q</code></td><td><code>uv run --extra dev ruff check src tests</code><br><code>uv run --extra dev ruff format --check src tests</code></td><td><code>uv build --wheel</code></td></tr><tr><td><code>ershu-worker</code></td><td><code>uv sync --locked --extra dev</code></td><td><code>uv run pytest -q</code></td><td><code>uv run ruff check src tests scripts</code><br><code>uv run ruff format --check src tests scripts</code></td><td><code>uv build --no-sources</code></td></tr><tr><td><code>ershu-mcp</code></td><td><code>uv sync --locked</code></td><td><code>uv run pytest -q</code></td><td><code>uv run ruff check src tests</code><br><code>uv run ruff format --check src tests</code></td><td><code>uv build --no-sources</code></td></tr></tbody></table><p>外部服务测试需要单独准备 PostgreSQL、Milvus 或 Docker，不能用普通单元测试代替。</p><h2 id="前端-frontend" tabindex="-1">前端 <code>frontend</code> <a class="header-anchor" href="#前端-frontend" aria-label="Permalink to &quot;前端 `frontend`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目的</th><th>命令</th></tr></thead><tbody><tr><td>按锁文件安装</td><td><code>npm ci</code></td></tr><tr><td>启动开发服务器</td><td><code>npm run dev</code></td></tr><tr><td>运行测试</td><td><code>npm test</code></td></tr><tr><td>检查代码与类型</td><td><code>npm run lint</code></td></tr><tr><td>检查格式</td><td><code>npm run format:check</code></td></tr><tr><td>生产构建</td><td><code>npm run build</code></td></tr><tr><td>预览构建结果</td><td><code>npm run preview</code></td></tr></tbody></table><p>中文开发地址是 <code>http://localhost:3000/#/zh</code>，英文地址是 <code>http://localhost:3000/#/en</code>。</p><h2 id="文档站-ershu-docs" tabindex="-1">文档站 <code>ershu-docs</code> <a class="header-anchor" href="#文档站-ershu-docs" aria-label="Permalink to &quot;文档站 `ershu-docs`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目的</th><th>命令</th></tr></thead><tbody><tr><td>按锁文件安装</td><td><code>npm ci</code></td></tr><tr><td>本地编写</td><td><code>npm run dev</code></td></tr><tr><td>检查双语页面、链接和排版</td><td><code>npm run check:content</code></td></tr><tr><td>检查格式</td><td><code>npm run format:check</code></td></tr><tr><td>生产构建</td><td><code>npm run build</code></td></tr><tr><td>运行全部检查</td><td><code>npm run check</code></td></tr><tr><td>预览构建结果</td><td><code>npm run preview</code></td></tr></tbody></table><p>开发服务器默认使用 <code>http://127.0.0.1:5173</code>。</p>',15)])])}const m=d(c,[["render",s]]);export{p as __pageData,m as default};
